/** 已有划痕里**正好覆盖**这一段的那一道（用来判断"这一段已经有笔了"）。 */
export function sameRange(marks: Mark[], seg: Seg): Mark | undefined {
  return marks.find((m) => m.block_id === seg.blockId && m.lang === seg.lang
    && m.start === seg.start && m.end === seg.end)
}

