def measure():
    return js("""(() => {
      const en = document.querySelectorAll('.t-en'), zh = document.querySelectorAll('.t-zh');
      const vis = (els) => [...els].filter(e => getComputedStyle(e).display !== 'none' && e.getClientRects().length).length;
