              noteLines: note ? note.textContent.split('\\n').length : null,
              noteVisible: note ? (getComputedStyle(note).display !== 'none') : null,
              ruleAbove: nb, overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth};
    })()""")

